// Serializable EmployeeBean
import java.io.*;public class Q03 {public static class EmployeeBean implements Serializable {private static final long serialVersionUID=1L;private int empId;private String empName;private double salary;public EmployeeBean(){}public int getEmpId(){return empId;}public void setEmpId(int v){empId=v;}public String getEmpName(){return empName;}public void setEmpName(String v){empName=v;}public double getSalary(){return salary;}public void setSalary(double v){salary=v;}}public static void main(String[] args)throws Exception{EmployeeBean b=new EmployeeBean();b.setEmpId(5);b.setEmpName("Ravi");b.setSalary(45000);ByteArrayOutputStream out=new ByteArrayOutputStream();try(ObjectOutputStream o=new ObjectOutputStream(out)){o.writeObject(b);}try(ObjectInputStream in=new ObjectInputStream(new ByteArrayInputStream(out.toByteArray()))){EmployeeBean copy=(EmployeeBean)in.readObject();System.out.println(copy.getEmpName()+" "+copy.getSalary());}}}
